pragma solidity ^0.8.28;

/// @custom:evm-version cancun

// Interfaces for Uniswap Router and Factory
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable returns (uint[] memory amounts);
    function swapExactTokensForETH(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

// Ownable Contract
abstract contract Ownable {
    address private _owner;
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    constructor() {
        _owner = msg.sender;
        emit OwnershipTransferred(address(0), _owner);
    }

    function owner() public view returns (address) {
        return _owner;
    }

    modifier onlyOwner() {
        require(owner() == msg.sender, "Caller is not the owner");
        _;
    }
}

// ReentrancyGuard Contract
abstract contract ReentrancyGuard {
    uint256 private constant _NOT_ENTERED = 1;
    uint256 private constant _ENTERED = 2;
    uint256 private _status;

    constructor() {
        _status = _NOT_ENTERED;
    }

    modifier nonReentrant() {
        require(_status != _ENTERED, "ReentrancyGuard: reentrant call");
        _status = _ENTERED;
        _;
        _status = _NOT_ENTERED;
    }
}

// Sniping Bot Contract
contract UniswapSniperBot is ReentrancyGuard, Ownable {
    IUniswapV2Router02 public immutable uniswapRouter;
    address public immutable WETH;
    bool public botActive;
    uint256 public profitThreshold;
    uint256 public stopLossThreshold;
    uint256 public constant MAX_ETH_SPEND = 0.05 ether; // Adjustable limit

    event SnipeExecuted(address indexed token, uint256 ethSpent, uint256 tokensReceived);
    event TokensSold(address indexed token, uint256 tokensSold, uint256 ethReceived);
    event Withdrawn(address indexed to, uint256 amount);
    event BotStatusChanged(bool active);
    event StopLossHit(address indexed token, uint256 amountSold, uint256 ethReceived);

    constructor(address _router, uint256 _profitThreshold, uint256 _stopLossThreshold) {
        require(_router != address(0), "Invalid router address");
        uniswapRouter = IUniswapV2Router02(_router);
        WETH = uniswapRouter.WETH();
        profitThreshold = _profitThreshold;
        stopLossThreshold = _stopLossThreshold;
        botActive = false;
    }

    function startBot() external onlyOwner {
        botActive = true;
        emit BotStatusChanged(true);
    }

    function stopBot() external onlyOwner {
        botActive = false;
        emit BotStatusChanged(false);
    }

    function setProfitThreshold(uint256 _threshold) external onlyOwner {
        profitThreshold = _threshold;
    }

    function setStopLossThreshold(uint256 _threshold) external onlyOwner {
        stopLossThreshold = _threshold;
    }

    function getPathForETHToToken(address token) private view returns (address[] memory path) {
        path = new address[](2);
        path[0] = WETH;
        path[1] = token;
        return path;
    }

    function getPathForTokenToETH(address token) private view returns (address[] memory path) {
        path = new address[](2);
        path[0] = token;
        path[1] = WETH;
        return path;
    }

    function detectAndSnipe(address token, uint256 ethAmount, uint256 minTokensOut) external onlyOwner payable {
        require(botActive, "Bot is not active");
        require(address(this).balance >= ethAmount, "Insufficient ETH");
        require(ethAmount <= MAX_ETH_SPEND, "Exceeds max ETH spend limit");
        require(token != address(0), "Invalid token");

        address[] memory path = getPathForETHToToken(token);

        uint256[] memory amounts = uniswapRouter.swapExactETHForTokens{value: ethAmount}(
            minTokensOut,
            path,
            address(this),
            block.timestamp + 300
        );

        emit SnipeExecuted(token, ethAmount, amounts[1]);
    }

    function autoSell(address token, uint256 minEthOut) external onlyOwner nonReentrant {
        require(botActive, "Bot is not active");
        require(token != address(0), "Invalid token");

        uint256 balance = IERC20(token).balanceOf(address(this));
        require(balance > 0, "No tokens to sell");

        IERC20(token).approve(address(uniswapRouter), balance);

        address[] memory path = getPathForTokenToETH(token);

        uint256[] memory amounts = uniswapRouter.swapExactTokensForETH(
            balance,
            minEthOut,
            path,
            address(this),
            block.timestamp + 300
        );

        emit TokensSold(token, balance, amounts[1]);
    }

    function withdrawETH() external onlyOwner nonReentrant {
        uint256 balance = address(this).balance;
        require(balance > 0, "No ETH to withdraw");

        (bool success, ) = payable(owner()).call{value: balance}("");
        require(success, "ETH withdrawal failed");

        emit Withdrawn(owner(), balance);
    }

    function withdrawTokens(address token) external onlyOwner nonReentrant {
        require(token != address(0), "Invalid token");
        uint256 balance = IERC20(token).balanceOf(address(this));
        require(balance > 0, "No tokens to withdraw");

        bool success = IERC20(token).transfer(owner(), balance);
        require(success, "Token withdrawal failed");
    }

    function getTokenBalance(address token) public view returns (uint256) {
        return IERC20(token).balanceOf(address(this));
    }

    receive() external payable {}
}
